'use strict';

// MODULES //

var isinfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var lnf = require( '@stdlib/math/base/special/lnf' );
var sqrtf = require( '@stdlib/math/base/special/sqrtf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// VARIABLES //

var ONE = f32( 1.0 );


// MAIN //

/**
* Computes the hyperbolic arccosine of a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} hyperbolic arccosine (in radians)
*
* @example
* var v = acoshf( 1.0 );
* // returns 0.0
*
* @example
* var v = acoshf( 2.0 );
* // returns ~1.317
*
* @example
* var v = acoshf( NaN );
* // returns NaN
*/
function acoshf( x ) {
	x = f32( x );
	if ( x < ONE ) {
		return NaN;
	}
	if ( isnanf( x ) || isinfinitef( x ) ) {
		return x;
	}
	return lnf( x + f32( sqrtf( f32( x+ONE ) )*sqrtf( f32( x-ONE ) ) ) );
}


// EXPORTS //

module.exports = acoshf;
